@Controller( controllerJsp = "ManageBatchs.jsp", controllerPath = "jsp/admin/plugins/identityimport/", right = "IDENTITYIMPORT_BATCH_MANAGEMENT", securityTokenEnabled = true )
public class BatchJspBean extends AbstractManageItemsJspBean<Integer, WorkflowBean<Batch>>
{
  (...)
    // Workflow
    private static final String BATCH_RESOURCE_TYPE = Batch.RESOURCE_TYPE;
    private static final int BATCH_WORKFLOW_KEY = 100;
    private WorkflowBeanService<Batch> _wfBeanService = new WorkflowBeanService<>( BATCH_RESOURCE_TYPE, BATCH_WORKFLOW_KEY );

    @Inject
    private Models _models;

    // Session variable to store working values
    private Batch _batch;
    WorkflowBean<Batch> _wfBean;


  (...)


    @Override
    List<WorkflowBean<Batch>> getItemsFromIds( List<Integer> listIds )
    {
        List<Batch> listBatch = BatchHome.getBatchsListByIds( listIds );

        // keep original order
        return listbatchWFBean.stream( ).sorted( Comparator.comparingInt( notif -> listIds.indexOf( notif.getId( ) ) ) )
                .map( b -> _wfBeanService.createWorkflowBean( b, b.getId( ), getUser( ) ) )
                .collect( Collectors.toList( ) );
    }

   (...)


    @Action( ACTION_CREATE_BATCH )
    public String doCreateBatch( HttpServletRequest request ) throws AccessDeniedException
    {
        populate( _batch, request, getLocale( ) );

  (...)

        BatchHome.create( _batch );
        _wfBean = _wfBeanService.createWorkflowBean( _batch, _batchWFBean.getId( ), getUser( ) );

        return redirectView( request, VIEW_MANAGE_BATCHS );
    }

  (...)

    @View( VIEW_MODIFY_BATCH )
    public String getModifyBatch( HttpServletRequest request )
    {
        int nId = Integer.parseInt( request.getParameter( PARAMETER_ID_BATCH ) );

        if ( _batch == null || ( _batchWFBean.getId( ) != nId ) )
        {
            Optional<Batch> optBatch = BatchHome.findByPrimaryKey( nId );
            _batch = optbatchWFBean.orElseThrow( ( ) -> new AppException( ERROR_RESOURCE_NOT_FOUND ) );

            _wfBean = _wfBeanService.createWorkflowBean( _batch, _batchWFBean.getId( ), getUser( ) );
        }

        _wfBeanService.addHistory(_wfBean, request, getLocale( ) );

        _models.put( MARK_BATCH, _wfBean );

        return getPage( PROPERTY_PAGE_TITLE_MODIFY_BATCH, TEMPLATE_MODIFY_BATCH );
    }

  (...)

    /**
     * process a workflow action
     *
     * @param request
     *            The Http request
     * @return the jsp URL to display the form to manage batchs
     */
    @Action( ACTION_PROCESS_WORKFLOW_ACTION )
    public String doProcessAction( HttpServletRequest request )
    {
        int nId = Integer.parseInt( request.getParameter( PARAMETER_ID_BATCH ) );
        int nAction = Integer.parseInt( request.getParameter( PARAMETER_ID_ACTION ) );

        if ( _batch == null || ( _batchWFBean.getId( ) != nId ) )
        {
            Optional<Batch> optBatch = BatchHome.findByPrimaryKey( nId );
            _batch = optbatchWFBean.orElseThrow( ( ) -> new AppException( ERROR_RESOURCE_NOT_FOUND ) );

            _wfBean = _wfBeanService.createWorkflowBean( _batch, _batchWFBean.getId( ), getUser( ) );
        }

        String strFeedToken = _wfBeanService.processAction(_wfBean, nAction, request, getLocale( ) );        

        if ( strFeedToken != null )
        {

            _models.put( MARK_FEED_TOKEN, strFeedToken );

            return getPage( PROPERTY_PAGE_TITLE_PROCESS_BATCH, TEMPLATE_PROCESS_BATCH );
        }
        else
        {
            return redirect( request, VIEW_MODIFY_BATCH, PARAMETER_ID_BATCH, nId );
        }
    }
}
